    for root, dirs, files in os.walk(source):
        for f in files:
            src = os.path.join(root, f)
            dst = os.path.join(destination, f)

            if hashlib.md5(open(src, 'rb').read()).hexdigest() != hashlib.md5(open(dst, 'rb').read()).hexdigest():
